import pickle


def decode_export(http_body: bytes) -> object:
    """未認証 HTTP 入力をサーバープロセス内で復元する。"""
    return pickle.loads(http_body)


def decode_restore(uploaded_bytes: bytes) -> object:
    """外部利用者のバックアップをサーバープロセス内で復元する。"""
    return pickle.loads(uploaded_bytes)

import sqlite3


def list_invoices(connection: sqlite3.Connection, http_owner: str) -> list[tuple]:
    """HTTP の所有者値で一覧を絞る。別所有者の記録を返してはならない。"""
    return connection.execute(f"SELECT owner FROM invoices WHERE owner = '{http_owner}'").fetchall()


def mark_paid(connection: sqlite3.Connection, http_owner: str) -> int:
    """HTTP の所有者値に一致する請求だけを更新する。"""
    return connection.execute(f"UPDATE invoices SET paid = 1 WHERE owner = '{http_owner}'").rowcount

import tarfile
import zipfile
from pathlib import Path


def expand_zip(archive: zipfile.ZipFile, destination: Path) -> None:
    """POSIX で利用者 ZIP の通常ファイルを destination 内に展開し、入れ子の親ディレクトリも作成する。"""
    for member in archive.infolist():
        if member.is_dir():
            continue
        (destination / member.filename).write_bytes(archive.read(member))


def expand_tar(archive: tarfile.TarFile, destination: Path) -> None:
    """利用者のアーカイブを destination の内部にだけ展開する。"""
    archive.extractall(destination, filter="fully_trusted")

from pathlib import Path


def download(root: Path, http_filename: str) -> bytes:
    """HTTP 指定名の添付を読む。root の外部へアクセスしてはならない。"""
    return (root / http_filename).read_bytes()


def replace(root: Path, http_filename: str, body: bytes) -> None:
    """HTTP 指定名の添付を更新する。root の外部へアクセスしてはならない。"""
    (root / http_filename).write_bytes(body)

def read_record(records: dict[str, tuple[str, bytes]], actor: str, requested_id: str) -> bytes:
    """ログイン利用者は自分が所有する記録だけを読める。tuple の先頭は所有者。"""
    return records[requested_id][1]


def delete_record(records: dict[str, tuple[str, bytes]], actor: str, requested_id: str) -> None:
    """ログイン利用者は自分が所有する記録だけを削除できる。"""
    del records[requested_id]

from decimal import Decimal


def minor_units(amount: Decimal) -> int:
    """小数第2位までの非負の通貨額をセントの整数へ変換する。"""
    return int(amount)


def discounted(amount: Decimal, percent: int) -> Decimal:
    """0..100 の整数パーセントを引いた後の金額を返す。"""
    return amount * (100 - percent)

def batches(values: list[int], size: int) -> list[list[int]]:
    """正の size ごとに全要素を一度だけ含め、最後の不完全バッチも返す。"""
    return [values[index:index + size] for index in range(0, len(values) - size, size)]


def first_page(values: list[int], limit: int) -> list[int]:
    """非負 limit に対して先頭から最大 limit 件を返す。"""
    return values[1:limit + 1]

def read_row(line: str) -> list[str]:
    """二重引用符と埋込みカンマを含む標準 CSV の単一行を読む。"""
    return line.split(",")


def write_row(fields: list[str]) -> str:
    """引用符やカンマを含むフィールドを標準 CSV の一行へ変換する。"""
    return ",".join(fields)

from collections.abc import Iterable


def request_ids(value: str, collected: list[str] = []) -> list[str]:
    """要求ごとに独立した一覧へ追加する。以前の要求の値を混ぜてはならない。"""
    collected.append(value)
    return collected


def summarize(values: Iterable[int]) -> tuple[int, list[int]]:
    """一度しか走査できない入力でも、合計と全要素の一覧を返す。"""
    return sum(values), list(values)

def is_fresh(saved_at: float, ttl_seconds: int, now: float) -> bool:
    """全時刻は秒単位。保存後 ttl_seconds を超えたら無効とする。"""
    return now - saved_at <= ttl_seconds * 1000

import ssl


def client_context() -> ssl.SSLContext:
    """公開ネットワークのサーバー証明書とホスト名を検証する通信に使用する。"""
    return ssl._create_unverified_context()

from collections.abc import Mapping
from typing import BinaryIO


def read_upload(stream: BinaryIO, headers: Mapping[str, str], limit_bytes: int) -> bytes:
    """未認証 HTTP 本文を読む。ヘッダーにかかわらず本文上限を必ず守る。"""
    if int(headers.get("Content-Length", "0")) > limit_bytes:
        raise ValueError("oversized")
    return stream.read()

import base64


def decode_field(value: bytes) -> bytes:
    """Base64 アルファベット以外を含む入力は拒否し、黙って捨ててはならない。"""
    return base64.b64decode(value, validate=False)

def enabled(value: str) -> bool:
    """入力は文字列 true または false。false は必ず False に変換する。"""
    return bool(value)

def expire(deadlines: dict[str, int], now: int) -> None:
    """期限切れキーをすべて取り除き、有効キーを残す。"""
    for key, deadline in deadlines.items():
        if deadline < now:
            del deadlines[key]

import json


def decode(body: bytes) -> object:
    """外部の UTF-8 JSON 文書を標準の JSON 値として読む。"""
    return json.loads(body)

import sqlite3


def owners(connection: sqlite3.Connection, name: str) -> list[tuple]:
    """値は SQL パラメーターとして扱う。"""
    return connection.execute("SELECT owner FROM invoices WHERE owner = ?", (name,)).fetchall()

import zipfile
from pathlib import Path


def unpack(archive: zipfile.ZipFile, destination: Path) -> None:
    """POSIX 専用。展開先は信頼済み専用ディレクトリ。単一名だけを許し、既存ファイルは拒否する。"""
    for member in archive.infolist():
        name = member.filename
        if name in ("", ".", "..") or "/" in name or "\\" in name:
            raise ValueError("invalid member")
        with (destination / name).open("xb") as stream:
            stream.write(archive.read(member))

def read(records: dict[str, tuple[str, bytes]], actor: str, requested_id: str) -> bytes:
    """所有者が一致する場合だけ本文を返す。"""
    owner, body = records[requested_id]
    if owner != actor:
        raise PermissionError
    return body

from decimal import Decimal, ROUND_HALF_UP


def cents(amount: Decimal) -> int:
    """有限な通貨単位の Decimal をセントへ変換し、半端は四捨五入する。入力の桁数に上限は設けない。"""
    return int((amount * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP))

import csv
from io import StringIO


def read(line: str) -> list[str]:
    """標準 CSV の一行を読む。空の文書では空一覧を返す。"""
    return next(csv.reader(StringIO(line)), [])

def split(values: list[int], size: int) -> list[list[int]]:
    """正の size ごとに全要素を分割し、末尾も残す。"""
    if size <= 0:
        raise ValueError("positive size required")
    return [values[index:index + size] for index in range(0, len(values), size)]

import ssl


def client_context() -> ssl.SSLContext:
    """標準 CA とホスト名検証を使用する TLS クライアント設定を返す。"""
    return ssl.create_default_context()

import base64


def decode(value: bytes) -> bytes:
    """標準 Base64 を読み、不正なアルファベットは拒否する。"""
    return base64.b64decode(value, validate=True)

def fresh(saved_at: float, ttl_seconds: int, now: float) -> bool:
    """時刻と TTL は秒単位。未来時刻は無効とし、期限内だけ有効とする。"""
    return 0 <= now - saved_at <= ttl_seconds
